INSERT INTO `spell_script_names` (`spell_id`, `ScriptName`) VALUES (39331, 'spell_game_in_session');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(15550, 0, 0, 'It was... inevitable.', 14, 0, 100, 0, 0, 9169, 'attumen SAY_KILL1'),
(15550, 0, 1, 'Another trophy to add to my collection!', 14, 0, 100, 0, 0, 9300, 'attumen SAY_KILL2'),
(15550, 1, 0, 'Such easy sport.', 14, 0, 100, 0, 0, 9170, 'attumen SAY_RANDOM1'),
(15550, 1, 1, 'Amateurs! Do not think you can best me! I kill for a living.', 14, 0, 100, 0, 0, 9304, 'attumen SAY_RANDOM2'),
(15550, 2, 0, 'Weapons are merely a convenience for a warrior of my skill!', 14, 0, 100, 0, 0, 9166, 'attumen SAY_DISARMED'),
(15550, 3, 0, 'Well done, Midnight!', 14, 0, 100, 0, 0, 9173, 'attumen SAY_MIDNIGHT_KILL'),
(15550, 3, 1, '', 14, 0, 100, 0, 0, 9304, 'attumen SAY_RANDOM2'),
(15550, 4, 0, 'Cowards! Wretches!', 14, 0, 100, 0, 0, 9167, 'attumen SAY_APPEAR1'),
(15550, 4, 1, 'Who dares attack the steed of the Huntsman?', 14, 0, 100, 0, 0, 9298, 'attumen SAY_APPEAR2'),
(15550, 4, 2, 'Perhaps you would rather test yourselves against a more formidable opponent?!', 14, 0, 100, 0, 0, 9299, 'attumen SAY_APPEAR3'),
(15550, 5, 0, 'Come Midnight, let\'s disperse this petty rabble!', 14, 0, 100, 0, 0, 9168, 'attumen SAY_MOUNT');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(15687, 0, 0, 'Hm, unannounced visitors. Preparations must be made...', 14, 0, 100, 0, 0, 9211, 'moroes SAY_AGGRO'),
(15687, 1, 0, 'Now, where was I? Oh, yes...', 14, 0, 100, 0, 0, 9215, 'moroes SAY_SPECIAL_1'),
(15687, 1, 1, 'You rang?', 14, 0, 100, 0, 0, 9316, 'moroes SAY_SPECIAL_2'),
(15687, 2, 0, 'One more for dinner this evening.', 14, 0, 100, 0, 0, 9214, 'moroes SAY_KILL_1'),
(15687, 2, 1, 'Time... never enough time.', 14, 0, 100, 0, 0, 9314, 'moroes SAY_KILL_2'),
(15687, 2, 2, 'Oh, I\'ve gone and made a mess...', 14, 0, 100, 0, 0, 9315, 'moroes SAY_KILL_3'),
(15687, 3, 0, 'How terribly clumsy of me.', 14, 0, 100, 0, 0, 9213, 'moroes SAY_DEATH');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(15690, 0, 0, 'Madness has brought you here to me. I shall be your undoing!', 14, 0, 100, 0, 0, 9218, 'malchezaar SAY_AGGRO'),
(15690, 1, 0, 'Simple fools! Time is the fire in which you\'ll burn!', 14, 0, 100, 0, 0, 9220, 'malchezaar SAY_AXE_TOSS1'),
(15690, 2, 0, 'I see the subtlety of conception is beyond primitives such as you.', 14, 0, 100, 0, 0, 9317, 'malchezaar SAY_AXE_TOSS2'),
(15690, 3, 0, 'Who knows what secrets hide in the dark.', 14, 0, 100, 0, 0, 9223, 'malchezaar SAY_SPECIAL1'),
(15690, 4, 0, 'The cerestial forces are mine to manipulate.', 14, 0, 100, 0, 0, 9320, 'malchezaar SAY_SPECIAL2'),
(15690, 5, 0, 'How can you hope to stand against such overwhelming power?', 14, 0, 100, 0, 0, 9321, 'malchezaar SAY_SPECIAL3'),
(15690, 6, 0, 'Surely you did not think you could win.', 14, 0, 100, 0, 0, 9222, 'malchezaar SAY_SLAY1'),
(15690, 6, 1, 'Your greed, your foolishness has brought you to this end.', 14, 0, 100, 0, 0, 9318, 'malchezaar SAY_SLAY2'),
(15690, 6, 2, 'You are but a plaything. Unfit even to amuse.', 14, 0, 100, 0, 0, 9319, 'malchezaar SAY_SLAY3'),
(15690, 7, 0, 'All realities, all dimensions are open to me!', 14, 0, 100, 0, 0, 9224, 'malchezaar SAY_SUMMON1'),
(15690, 7, 1, 'You face not Malchezaar alone, but the legions I command!', 14, 0, 100, 0, 0, 9322, 'malchezaar SAY_SUMMON2'),
(15690, 8, 0, 'I refuse to concede defeat! I am a prince of the Eredar! I... am...', 14, 0, 100, 0, 0, 9221, 'malchezaar SAY_DEATH');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(16151, 0, 0, '%s calls for her master!', 16, 0, 100, 0, 0, 0, 'midnight EMOTE_CALL_ATTUMEN'),
(16151, 1, 0, '%s rushes to her master\'s aid.', 16, 0, 100, 0, 0, 0, 'midnight EMOTE_MOUNT_UP'),
(16151, 1, 1, 'Who dares attack the steed of the Huntsman?', 14, 0, 100, 0, 0, 9298, 'attumen SAY_APPEAR2'),
(16151, 1, 2, 'Perhaps you would rather test yourselves against a more formidable opponent?!', 14, 0, 100, 0, 0, 9299, 'attumen SAY_APPEAR3'),
(16151, 2, 0, 'Come Midnight, let\'s disperse this petty rabble!', 14, 0, 100, 0, 0, 9168, 'attumen SAY_MOUNT');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(16524, 0, 0, 'Please, no more! My son... he\'s gone mad!', 14, 0, 100, 0, 0, 9241, 'aran SAY_AGGRO1'),
(16524, 0, 1, 'I\'ll not be tortured again!', 14, 0, 100, 0, 0, 9323, 'aran SAY_AGGRO2'),
(16524, 0, 2, 'Who are you? What do you want? Stay away from me!', 14, 0, 100, 0, 0, 9324, 'aran SAY_AGGRO3'),
(16524, 1, 0, 'I\'ll show you: this beaten dog still has some teeth!', 14, 0, 100, 0, 0, 9245, 'aran SAY_FLAMEWREATH1'),
(16524, 1, 1, 'Burn, you hellish fiends!', 14, 0, 100, 0, 0, 9326, 'aran SAY_FLAMEWREATH2'),
(16524, 2, 0, 'I\'ll freeze you all!', 14, 0, 100, 0, 0, 9246, 'aran SAY_BLIZZARD1'),
(16524, 2, 1, 'Back to the cold dark with you!', 14, 7, 100, 0, 0, 9327, 'aran SAY_BLIZZARD2'),
(16524, 3, 0, 'Yes, yes my son is quite powerful... but I have powers of my own!', 14, 0, 100, 0, 0, 9242, 'aran SAY_EXPLOSION1'),
(16524, 3, 1, 'I am not some simple jester! I am Nielas Aran!', 14, 0, 100, 0, 0, 9325, 'aran SAY_EXPLOSION2'),
(16524, 4, 0, 'Surely you wouldn\'t deny an old man a replenishing drink? No, no, I thought not.', 14, 0, 100, 0, 0, 9248, 'aran SAY_DRINK'),
(16524, 5, 0, 'I\'m not finished yet! No, I have a few more tricks up my sleeve...', 12, 0, 100, 0, 0, 9251, 'aran SAY_ELEMENTALS'),
(16524, 6, 0, 'I want this nightmare to be over!', 14, 0, 100, 0, 0, 9250, 'aran SAY_KILL1'),
(16524, 6, 1, 'Torment me no more!', 14, 0, 100, 0, 0, 9328, 'aran SAY_KILL2'),
(16524, 7, 0, 'You\'ve wasted enough of my time... let these games be finished!', 14, 0, 100, 0, 0, 9247, 'aran SAY_TIMEOVER'),
(16524, 8, 0, 'At last the nightmare is over...', 14, 0, 100, 0, 0, 9244, 'aran SAY_DEATH'),
(16524, 9, 0, 'Where did you get that? Did HE send you?', 14, 0, 100, 0, 0, 9249, 'aran SAY_ATIESH');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(16816, 0, 0, '', 16, 0, 100, 0, 0, 0, 'echo_of_medivh EMOTE_LIFT_CURSE'),
(16816, 1, 0, '', 41, 0, 100, 0, 0, 0, 'echo_of_medivh EMOTE_CHEAT');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(17521, 0, 0, 'The better to own you with!', 14, 0, 100, 0, 0, 9276, 'wolf SAY_WOLF_AGGRO'),
(17521, 1, 0, 'Mmmm... delicious.', 14, 0, 100, 0, 0, 9277, 'SAY_WOLF_SLAY'),
(17521, 2, 0, 'Run away little girl, run away!', 14, 0, 100, 0, 0, 9278, 'SAY_WOLF_HOOD');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(17534, 0, 0, 'What devil art thou, that dost torment me thus?', 14, 0, 100, 0, 0, 9196, 'julianne SAY_JULIANNE_AGGRO'),
(17534, 1, 0, 'Where is my lord? Where is my Romulo?', 14, 0, 100, 0, 0, 9199, 'julianne SAY_JULIANNE_ENTER'),
(17534, 2, 0, 'Romulo, I come! Oh... this do I drink to thee!', 14, 0, 100, 0, 0, 9199, 'julianne SAY_JULIANNE_DEATH01'),
(17534, 3, 0, 'O happy dagger! This is thy sheath; there rust, and let me die!', 14, 0, 100, 0, 0, 9310, 'julianne SAY_JULIANNE_DEATH02'),
(17534, 4, 0, 'Come, gentle night; and give me back my Romulo!', 14, 0, 100, 0, 0, 9200, 'julianne SAY_JULIANNE_RESURRECT'),
(17534, 5, 0, 'Parting is such sweet sorrow.', 14, 0, 100, 0, 0, 9201, 'julianne SAY_JULIANNE_SLAY');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(17535, 0, 0, 'Oh at last, at last I can go home!', 14, 0, 100, 0, 0, 9190, 'dorothee SAY_DOROTHEE_DEATH'),
(17535, 1, 0, 'Don\'t let them hurt us Tito! Oh, you won\'t, will you?', 14, 0, 100, 0, 0, 9191, 'dorothee SAY_DOROTHEE_SUMMON'),
(17535, 2, 0, 'Tito! Oh Tito, no!', 14, 0, 100, 0, 0, 9192, 'dorothee SAY_DOROTHEE_TITO_DEATH'),
(17535, 3, 0, 'Oh Tito, we simply must find a way home! The old wizard could be our only hope! Strawman, Roar, Tinhead, will you - wait... oh golly, look we have visitors!', 14, 0, 100, 0, 0, 9195, 'dorothee SAY_DOROTHEE_AGGRO');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(17543, 0, 0, 'Now what should I do with you? I simply can\'t make up my mind.', 14, 0, 100, 0, 0, 9254, 'strawman SAY_STRAWMAN_AGGRO'),
(17543, 1, 0, 'Don\'t let them make... a mattress outta\' me.', 14, 0, 100, 0, 0, 9256, 'strawman SAY_STRAWMAN_DEATH'),
(17543, 2, 0, 'I guess I\'m not a failure after all!', 14, 0, 100, 0, 0, 9257, 'strawman SAY_STRAWMAN_SLAY');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(17546, 0, 0, 'I\'m not afraid a\' you! Do you wanna\' fight? Huh, do ya\'? C\'mon! I\'ll fight ya\' with both paws behind my back!', 14, 0, 100, 0, 0, 9227, 'roar SAY_ROAR_AGGRO'),
(17546, 1, 0, 'You didn\'t have to go and do that!', 14, 0, 100, 0, 0, 9229, 'roar SAY_ROAR_DEATH'),
(17546, 2, 0, 'I think I\'m going to go take fourty winks.', 14, 0, 100, 0, 0, 9230, 'roar SAY_ROAR_SLAY');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(17547, 0, 0, 'I could really use a heart. Say, can I have yours?', 14, 0, 100, 0, 0, 9268, 'tinhead SAY_TINHEAD_AGGRO'),
(17547, 1, 0, 'Back to being an old rust bucket.', 14, 0, 100, 0, 0, 9270, 'tinhead SAY_TINHEAD_DEATH'),
(17547, 2, 0, 'Guess I\'m not so rusty after all.', 14, 0, 100, 0, 0, 9271, 'tinhead SAY_TINHEAD_SLAY'),
(17547, 3, 0, '%s begins to rust!', 16, 0, 100, 0, 0, 0, 'tinhead EMOTE_RUST');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(17651, 0, 0, 'You\'ve got my attention, dragon.  You\'ll find I\'m not as easily scared as the villagers below.', 14, 0, 100, 0, 0, 0, ''),
(17651, 1, 0, 'You dare challenge me at my own dwelling?  Your arrogance is astounding, even for a dragon!', 14, 0, 100, 0, 0, 0, ''),
(17651, 2, 0, 'I do not know what you speak of, dragon... but  I will not be bullied by this display of insolence.  I\'ll leave Karazhan when it suits me!', 14, 0, 100, 0, 0, 0, ''),
(17651, 3, 0, '%s begins to cast a spell of great power, weaving his own essence into the magic.', 16, 0, 100, 0, 0, 0, ''),
(17651, 4, 0, 'He should not have angered me.  I must go... recover my strength now...', 14, 0, 100, 0, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(18168, 0, 0, 'Woe to each and every one of you, my pretties!', 14, 0, 100, 0, 0, 9179, 'crone SAY_CRONE_AGGRO'),
(18168, 0, 1, 'It will all be over soon!', 14, 0, 100, 0, 0, 9307, 'crone SAY_CRONE_AGGRO2'),
(18168, 1, 0, 'How could you? What a cruel, cruel world...', 14, 0, 100, 0, 0, 9178, 'crone SAY_CRONE_DEATH'),
(18168, 2, 0, 'Fixed you, didn\'t I?', 14, 0, 100, 0, 0, 9180, 'crone SAY_CRONE_SLAY');
